import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double of the pricing downstream (mocking: inprocess, fake gateway).
const prices = { apple: 10, pear: 2.5, gold: 60 }
const pricing = { async priceOf(sku) { return prices[sku] } }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => new Promise((r) => server.close(r)))

const post = (body, raw) => fetch(`${base}/orders`, {
  method: 'POST', headers: { 'content-type': 'application/json' }, body: raw ?? JSON.stringify(body),
})

test('POST /orders creates an order: 201, JSON, echoed items, summed total', async () => {
  const res = await post({ items: [{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 2 }] })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const body = await res.json()
  assert.deepEqual(Object.keys(body).sort(), ['id', 'items', 'total'])
  assert.equal(typeof body.id, 'string')
  assert.deepEqual(body.items, [{ sku: 'apple', qty: 2 }, { sku: 'pear', qty: 2 }])
  assert.equal(body.total, 25)
})

test('POST /orders floors a fractional total', async () => {
  const body = await (await post({ items: [{ sku: 'pear', qty: 1 }] })).json()
  assert.equal(body.total, 2)
})

test('POST /orders: total of exactly 100 gets no discount', async () => {
  const body = await (await post({ items: [{ sku: 'apple', qty: 10 }] })).json()
  assert.equal(body.total, 100)
})

test('POST /orders: raw total above 100 gets 10% off', async () => {
  const body = await (await post({ items: [{ sku: 'gold', qty: 2 }] })).json()
  assert.equal(body.total, 108)
})

test('POST /orders assigns increasing string ids', async () => {
  const a = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  const b = await (await post({ items: [{ sku: 'apple', qty: 1 }] })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('POST /orders with missing, empty or non-array items: 400 items required', async () => {
  for (const payload of [{}, { items: [] }, { items: 'x' }]) {
    const res = await post(payload)
    assert.equal(res.status, 400)
    assert.equal(res.headers.get('content-type'), 'application/json')
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders with malformed JSON or empty body: 400 items required', async () => {
  for (const raw of ['{nope', '']) {
    const res = await post(undefined, raw)
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('POST /orders with unknown sku: 201 with null total', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — pricing returns undefined, total becomes NaN, serialised as null; order is still stored.
  const res = await post({ items: [{ sku: 'ghost', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('POST /orders accepts negative quantity', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — qty is not validated, so totals can be negative.
  const res = await post({ items: [{ sku: 'apple', qty: -1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, -10)
})

test('GET /orders/{id} returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'apple', qty: 3 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.equal(res.headers.get('content-type'), 'application/json')
  assert.deepEqual(await res.json(), created)
})

test('GET /orders/{id} for an unknown id answers 200 with an error body', async () => {
  // CHARACTERIZATION: current behaviour may be unintended — a missing order is 200, not 404.
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unrouted paths and methods answer 404 no route', async () => {
  const cases = [
    ['GET', '/'], ['GET', '/orders'], ['GET', '/orders/'], ['GET', '/orders/1/items'],
    ['PUT', '/orders'], ['DELETE', '/orders/1'], ['POST', '/orders/1'],
  ]
